var ou=new $APP.H(null,6,[Gu,iu(Eu,TE,!0,!0),$APP.IA,iu(VC,$APP.IA,!1,!1),$APP.QD,iu(nD,TE,!0,!0),hD,iu(QE,TE,!0,!0),$APP.Tq,iu($APP.ct,TE,!0,!0),Fu,iu(Fu,TE,!0,!0)],null);$APP.l($APP.ri($APP.fF,new $APP.H(null,1,[$APP.NE,$APP.FD],null)))&&($APP.l()&&((void 0).G?(void 0).G($u,"",null,null):(void 0).call(null,$u,"",null,null)),$APP.Dq($u,"amp.pages.not-found/not-found-view"));$APP.Vo("journal",{en:'{\n  "this-fits-this.title": "This Fits This",\n  "this-fits-this.summary": "A long plaster base carries the name Jasper Johns; twelve coloured slabs slot into it and lift out again. Zadik and Aram Zadikian on fitting, the handshake, the mould, and a work that is never arranged the same way twice.",\n  "the-weight-of-the-flag.title": "The Weight of the Flag",\n  "the-weight-of-the-flag.summary": "The first walk: green, white and red on three backs, from San Francesco della Vigna to Zanipolo. How one carried unit became a flag that walks, what Venice said to it, and the plan for the walks until the Biennale closes.",\n  "seven-steps-to-heaven.title": "The Making of Seven Steps to Heaven",\n  "seven-steps-to-heaven.summary": "Seven steps against the corner of two walls, rising to nowhere. From a pen sketch with a question on it, through nine versions and ten proportions of rise to run, to a stair carried by hand into Tesa 41.",\n  "making-a-flag.title": "Making a Flag",\n  "making-a-flag.summary": "Why would the Armenian Pavilion make an Italian flag? On Jasper Johns and things the mind already knows, three colours with no official meaning, an Armenian anthem that began with an Italian girl sewing a flag, and a flag that stands on its own feet.",\n  "carrying.title": "Carrying",\n  "carrying.summary": "One red unit on a back frame, carried out of Tesa 41, through the Arsenale gate and into Castello. On a city where everything moves by hand or by boat, the weight of representing a country, and the first time a work went out walking.",\n  "carried-by-hand.title": "Carried by Hand",\n  "carried-by-hand.summary": "In Venice every delivery ends on foot, one bridge at a time. On the realities of logistics in a city that resists the car, a summer away for visas, and the studio\'s return to full production.",\n  "the-studio-play-balance.title": "The Studio: Play, Balance, and the Life of Form",\n  "the-studio-play-balance.summary": "What happens when sculpture begins not with monumentality, but with a single, beautiful unit? At the heart of Zadik Zadikian’s work is a small plaster block—a tool for improvisation, rhythm, and thinking through form by touch.",\n  "blue-yellow-maquette.title": "Blue Yellow Blue Yellow",\n  "blue-yellow-maquette.summary": "Zadik Zadikian is developing a full-scale maquette of a new sculptural variation—an architectural test of structure, proportion, and chromatic rhythm.",\n  "kind.all": "All",\n  "kind.Venice": "Venice",\n  "kind.Process": "Process",\n  "kind.Studio": "Studio",\n  "kind.Maquette": "Maquette",\n  "author": "Armenian Pavilion Team"\n}\n',
it:'{\n  "this-fits-this.title": "Questo combacia con questo",\n  "this-fits-this.summary": "Una lunga base di gesso porta il nome Jasper Johns; dodici lastre colorate vi si incastrano e se ne sfilano. Zadik e Aram Zadikian sul combaciare, la stretta di mano, lo stampo e un’opera che non è mai disposta due volte allo stesso modo.",\n  "the-weight-of-the-flag.title": "Il peso della bandiera",\n  "the-weight-of-the-flag.summary": "La prima passeggiata: verde, bianco e rosso su tre schiene, da San Francesco della Vigna a Zanipolo. Come un elemento portato a spalla è diventato una bandiera che cammina, che cosa le ha detto Venezia e il programma delle passeggiate fino alla chiusura della Biennale.",\n  "seven-steps-to-heaven.title": "Come è nata Seven Steps to Heaven",\n  "seven-steps-to-heaven.summary": "Sette gradini contro l’angolo di due pareti, che salgono verso il nulla. Da uno schizzo a penna con una domanda, attraverso nove versioni e dieci proporzioni tra alzata e pedata, fino a una scala portata a mano nella Tesa 41.",\n  "making-a-flag.title": "Fare una bandiera",\n  "making-a-flag.summary": "Perché il Padiglione Armenia dovrebbe fare una bandiera italiana? Su Jasper Johns e le cose che la mente conosce già, tre colori senza un significato ufficiale, un inno armeno nato da una ragazza italiana che cuciva una bandiera, e una bandiera che sta in piedi da sola.",\n  "carrying.title": "Portare",\n  "carrying.summary": "Un elemento rosso su un telaio da spalla, portato fuori dalla Tesa 41, attraverso la porta dell’Arsenale e dentro Castello. Su una città dove tutto si muove a mano o in barca, sul peso di rappresentare un Paese e sulla prima volta che un’opera è uscita a piedi.",\n  "carried-by-hand.title": "Portato a mano",\n  "carried-by-hand.summary": "A Venezia ogni consegna finisce a piedi, un ponte alla volta. Sulla logistica in una città che resiste all’automobile, un’estate lontani per i visti e il ritorno dello studio alla piena produzione.",\n  "the-studio-play-balance.title": "Lo studio: gioco, equilibrio e la vita della forma",\n  "the-studio-play-balance.summary": "Che cosa succede quando la scultura non comincia dalla monumentalità, ma da un unico, bellissimo elemento? Al centro del lavoro di Zadik Zadikian c’è un piccolo blocco di gesso: uno strumento per improvvisare, trovare un ritmo e pensare la forma con le mani.",\n  "blue-yellow-maquette.title": "Blue Yellow Blue Yellow",\n  "blue-yellow-maquette.summary": "Zadik Zadikian sta sviluppando una maquette in scala reale di una nuova variazione scultorea: una prova architettonica di struttura, proporzione e ritmo cromatico.",\n  "kind.all": "Tutti",\n  "kind.Venice": "Venezia",\n  "kind.Process": "Processo",\n  "kind.Studio": "Studio",\n  "kind.Maquette": "Maquette",\n  "author": "Il team del Padiglione Armenia"\n}\n',
hy:'{\n  "this-fits-this.title": "Սա նստում է սրա մեջ",\n  "this-fits-this.summary": "Գիպսե երկար հիմքի վրա Jasper Johns անունն է, և տասներկու գունավոր սալ մտնում են նրա մեջ ու նորից դուրս գալիս։ Զադիկ և Արամ Զադիկյանները՝ իրար համապատասխանելու, ձեռքսեղմման, կաղապարի և մի գործի մասին, որը երբեք երկու անգամ նույն կերպ չի դասավորվում։",\n  "the-weight-of-the-flag.title": "Դրոշի ծանրությունը",\n  "the-weight-of-the-flag.summary": "Առաջին զբոսանքը՝ կանաչ, սպիտակ և կարմիր երեք մեջքի վրա, Սան Ֆրանչեսկո դելլա Վինյայից մինչև Զանիպոլո։ Ինչպես մեջքին տարված մեկ միավորը դարձավ քայլող դրոշ, ինչ ասաց նրան Վենետիկը և զբոսանքների ծրագիրը մինչև Բիենալեի փակումը։",\n  "seven-steps-to-heaven.title": "Ինչպես ստեղծվեց Seven Steps to Heaven-⁠ը",\n  "seven-steps-to-heaven.summary": "Յոթ աստիճան երկու պատերի անկյան դեմ, որ բարձրանում են դեպի ոչ մի տեղ։ Հարցով գրչանկարից՝ ինը տարբերակի և բարձրության ու խորության տասը համամասնության միջով, մինչև ձեռքով Tesa 41 տարված սանդուղք։",\n  "making-a-flag.title": "Դրոշ պատրաստել",\n  "making-a-flag.summary": "Ինչո՞ւ Հայաստանի տաղավարը պետք է իտալական դրոշ պատրաստի։ Ջասպեր Ջոնսի և այն բաների մասին, որոնք միտքն արդեն գիտի, երեք գույնի, որոնք պաշտոնական իմաստ չունեն, հայկական օրհներգի, որը սկսվեց դրոշ կարող իտալացի աղջկանից, և դրոշի, որը կանգնած է իր ոտքերի վրա։",\n  "carrying.title": "Տանել",\n  "carrying.summary": "Մեկ կարմիր միավոր՝ մեջքի շրջանակի վրա, դուրս տարված Tesa 41-⁠ից, Արսենալեի դարպասով, դեպի Կաստելլո։ Մի քաղաքի մասին, որտեղ ամեն ինչ շարժվում է ձեռքով կամ նավակով, երկիր ներկայացնելու ծանրության մասին և այն մասին, թե ինչպես գործն առաջին անգամ ոտքով դուրս եկավ։",\n  "carried-by-hand.title": "Ձեռքով տարված",\n  "carried-by-hand.summary": "Վենետիկում յուրաքանչյուր առաքում ավարտվում է ոտքով, մեկ կամուրջ միանգամից։ Մեքենային դիմադրող քաղաքում լոգիստիկայի իրողությունների, վիզաների պատճառով հեռու անցկացրած ամառվա և արվեստանոցի՝ լիարժեք աշխատանքի վերադարձի մասին։",\n  "the-studio-play-balance.title": "Արվեստանոցը. խաղ, հավասարակշռություն և ձևի կյանք",\n  "the-studio-play-balance.summary": "Ի՞նչ է լինում, երբ քանդակը սկսվում է ոչ թե մոնումենտալությունից, այլ մեկ գեղեցիկ միավորից։ Զադիկ Զադիկյանի աշխատանքի սրտում փոքրիկ գիպսե բլոկ է՝ իմպրովիզի, ռիթմի և ձևը հպումով մտածելու գործիք։",\n  "blue-yellow-maquette.title": "Blue Yellow Blue Yellow",\n  "blue-yellow-maquette.summary": "Զադիկ Զադիկյանը մշակում է նոր քանդակային տարբերակի բնական չափի մակետ՝ կառուցվածքի, համամասնության և գունային ռիթմի ճարտարապետական փորձություն։",\n  "kind.all": "Բոլորը",\n  "kind.Venice": "Վենետիկ",\n  "kind.Process": "Ընթացք",\n  "kind.Studio": "Արվեստանոց",\n  "kind.Maquette": "Մակետ",\n  "author": "Հայաստանի տաղավարի թիմը"\n}\n'});
