$APP.UG=new $APP.H(null,5,[$APP.yv,"2026-10-22",$APP.Er,"Carrying",$APP.ZE,"journal/26-10-22-orig/arsenale-quay.jpg",$APP.QB,"/films/carrying",$APP.ZC,"/blog/carrying"],null);$APP.VG=new $APP.H(null,6,[$APP.ME,"w06",$APP.TB,"walks/accademia/poster-2026-11-10.jpg",$APP.pE,.7076,$APP.HE,"walks/accademia/locandina-2026-11-10-A3.pdf",$APP.UC,"https://www.accademiavenezia.it/eventi/zadik-zadikian-performance-e-incontro-con-l-artista-905.html",$APP.yE,"https://www.instagram.com/p/DfjyUypoaud/"],null);$APP.Vo("films",{en:'{\n  "jasper-johns.title": "Jasper Johns",\n  "jasper-johns.when": "October 2026",\n  "jasper-johns.where": "Tesa 41, Venice",\n  "jasper-johns.summary": "Twelve plaster slabs, each a different colour, slot upright into a long base engraved with the name Jasper Johns. Zadik and Aram Zadikian talk about forms that fit, a handshake, and an arrangement that will never come again.",\n  "the-weight-of-the-flag.title": "The Weight of the Flag",\n  "the-weight-of-the-flag.when": "November 2026",\n  "the-weight-of-the-flag.where": "Castello, Venice",\n  "the-weight-of-the-flag.summary": "The first walk: green, white and red carried on three backs from San Francesco della Vigna to Zanipolo. Heads turn, a passer-by calls it a tribute to Italy, and a conversation starts in a historic square.",\n  "seven-steps-to-heaven.title": "Seven Steps to Heaven",\n  "seven-steps-to-heaven.when": "October 2026",\n  "seven-steps-to-heaven.where": "Arsenale and Tesa 41, Venice",\n  "seven-steps-to-heaven.summary": "A stair of seven steps that goes nowhere, carried by hand into Tesa 41 and painted white: on cubes, journeys, the present, and a climb to heaven in a small space.",\n  "italian-flag.title": "The Italian Flag",\n  "italian-flag.when": "October 2026",\n  "italian-flag.where": "Tesa 41, Venice",\n  "italian-flag.summary": "Green, white and red panels on their own feet: a flag made from the pavilion’s units, and a conversation about play, roots and carrying the flag to San Marco.",\n  "carrying.title": "Carrying",\n  "carrying.when": "October 2026",\n  "carrying.where": "Arsenale and Castello, Venice",\n  "carrying.summary": "A red unit strapped to a back frame and carried through the Arsenale and the streets of Castello. In Venice everything moves by hand or by boat.",\n  "murano.title": "Murano",\n  "murano.when": "October 2026",\n  "murano.where": "Murano",\n  "murano.summary": "Furnaces, glassblowers and a conversation at the table: on Murano’s glass and on keeping a studio alive rather than a showroom.",\n  "before-the-flag.title": "Before the Flag",\n  "before-the-flag.when": "September 2026",\n  "before-the-flag.where": "Tesa 41, Venice",\n  "before-the-flag.summary": "A white crenellated form in the hall: vertigo, scale, the roof beams of the Arsenale, and how a simple unit becomes an assembly.",\n  "tesa-41-september.title": "In Tesa 41",\n  "tesa-41-september.when": "September 2026",\n  "tesa-41-september.where": "Tesa 41, Venice",\n  "tesa-41-september.summary": "The Italian flag in its foam state, interlocking parts, pigments and brushes as the studio fills with color.",\n  "maquette.title": "The Maquette",\n  "maquette.when": "February 2026",\n  "maquette.where": "Los Angeles",\n  "maquette.summary": "From sketch to 3D model to full-scale foam: squares, rectangles and proportion, tested by standing next to the form.",\n  "leaning-red.title": "Leaning Red",\n  "leaning-red.when": "February 2026",\n  "leaning-red.where": "Los Angeles",\n  "leaning-red.summary": "Building a tall form by hand in the garden studio, from cardboard and tape to a panel standing in the room. Music only."\n}\n',
it:'{\n  "jasper-johns.title": "Jasper Johns",\n  "jasper-johns.when": "Ottobre 2026",\n  "jasper-johns.where": "Tesa 41, Venezia",\n  "jasper-johns.summary": "Dodici lastre di gesso, ognuna di un colore diverso, si incastrano in piedi in una lunga base su cui è inciso il nome Jasper Johns. Zadik e Aram Zadikian parlano di forme che combaciano, di una stretta di mano e di una disposizione che non tornerà più.",\n  "the-weight-of-the-flag.title": "The Weight of the Flag",\n  "the-weight-of-the-flag.when": "Novembre 2026",\n  "the-weight-of-the-flag.where": "Castello, Venezia",\n  "the-weight-of-the-flag.summary": "La prima passeggiata: verde, bianco e rosso portati su tre schiene da San Francesco della Vigna a Zanipolo. La gente si gira, un passante la chiama un omaggio all’Italia e in un campo storico comincia una conversazione.",\n  "seven-steps-to-heaven.title": "Seven Steps to Heaven",\n  "seven-steps-to-heaven.when": "Ottobre 2026",\n  "seven-steps-to-heaven.where": "Arsenale e Tesa 41, Venezia",\n  "seven-steps-to-heaven.summary": "Una scala di sette gradini che non porta da nessuna parte, portata a mano nella Tesa 41 e dipinta di bianco: su cubi, viaggi, il presente e una salita al cielo in uno spazio piccolo.",\n  "italian-flag.title": "The Italian Flag",\n  "italian-flag.when": "Ottobre 2026",\n  "italian-flag.where": "Tesa 41, Venezia",\n  "italian-flag.summary": "Pannelli verdi, bianchi e rossi in piedi da soli: una bandiera fatta con gli elementi del padiglione, e una conversazione sul gioco, sulle radici e sul portare la bandiera fino a San Marco.",\n  "carrying.title": "Carrying",\n  "carrying.when": "Ottobre 2026",\n  "carrying.where": "Arsenale e Castello, Venezia",\n  "carrying.summary": "Un elemento rosso fissato a un telaio da spalla e portato attraverso l’Arsenale e le calli di Castello. A Venezia tutto si muove a mano o in barca.",\n  "murano.title": "Murano",\n  "murano.when": "Ottobre 2026",\n  "murano.where": "Murano",\n  "murano.summary": "Fornaci, soffiatori e una conversazione a tavola: sul vetro di Murano e sul tenere in vita uno studio invece di uno showroom.",\n  "before-the-flag.title": "Before the Flag",\n  "before-the-flag.when": "Settembre 2026",\n  "before-the-flag.where": "Tesa 41, Venezia",\n  "before-the-flag.summary": "Una forma bianca merlata nella sala: la vertigine, la scala, le travi del tetto dell’Arsenale e come un elemento semplice diventa un assemblaggio.",\n  "tesa-41-september.title": "In Tesa 41",\n  "tesa-41-september.when": "Settembre 2026",\n  "tesa-41-september.where": "Tesa 41, Venezia",\n  "tesa-41-september.summary": "La bandiera italiana allo stato di schiuma, parti a incastro, pigmenti e pennelli, mentre lo studio si riempie di colore.",\n  "maquette.title": "The Maquette",\n  "maquette.when": "Febbraio 2026",\n  "maquette.where": "Los Angeles",\n  "maquette.summary": "Dallo schizzo al modello 3D alla schiuma in scala reale: quadrati, rettangoli e proporzioni, messi alla prova stando accanto alla forma.",\n  "leaning-red.title": "Leaning Red",\n  "leaning-red.when": "Febbraio 2026",\n  "leaning-red.where": "Los Angeles",\n  "leaning-red.summary": "Costruire a mano una forma alta nello studio in giardino, dal cartone e dal nastro adesivo a un pannello in piedi nella stanza. Solo musica."\n}\n',
hy:'{\n  "jasper-johns.title": "Jasper Johns",\n  "jasper-johns.when": "Հոկտեմբեր 2026",\n  "jasper-johns.where": "Tesa 41, Վենետիկ",\n  "jasper-johns.summary": "Գիպսե տասներկու սալ, յուրաքանչյուրը՝ տարբեր գույնի, ուղղահայաց տեղավորվում են երկար հիմքի մեջ, որի վրա փորագրված է Jasper Johns անունը։ Զադիկ և Արամ Զադիկյանները խոսում են իրար համապատասխանող ձևերի, ձեռքսեղմման և մի դասավորության մասին, որն այլևս չի կրկնվի։",\n  "the-weight-of-the-flag.title": "The Weight of the Flag",\n  "the-weight-of-the-flag.when": "Նոյեմբեր 2026",\n  "the-weight-of-the-flag.where": "Կաստելլո, Վենետիկ",\n  "the-weight-of-the-flag.summary": "Առաջին զբոսանքը՝ կանաչ, սպիտակ և կարմիր, երեք մեջքի վրա Սան Ֆրանչեսկո դելլա Վինյայից մինչև Զանիպոլո։ Գլուխներ են շրջվում, մի անցորդ այն անվանում է հարգանքի տուրք Իտալիային, և պատմական հրապարակում զրույց է սկսվում։",\n  "seven-steps-to-heaven.title": "Seven Steps to Heaven",\n  "seven-steps-to-heaven.when": "Հոկտեմբեր 2026",\n  "seven-steps-to-heaven.where": "Արսենալե և Tesa 41, Վենետիկ",\n  "seven-steps-to-heaven.summary": "Յոթ աստիճանով սանդուղք, որ ոչ մի տեղ չի տանում, ձեռքով բերված Tesa 41 և սպիտակ ներկված՝ խորանարդների, ճամփորդությունների, ներկայի և փոքր տարածության մեջ դեպի երկինք բարձրանալու մասին։",\n  "italian-flag.title": "The Italian Flag",\n  "italian-flag.when": "Հոկտեմբեր 2026",\n  "italian-flag.where": "Tesa 41, Վենետիկ",\n  "italian-flag.summary": "Կանաչ, սպիտակ և կարմիր վահանակներ՝ իրենց ոտքերի վրա. տաղավարի միավորներից պատրաստված դրոշ և զրույց խաղի, արմատների և դրոշը մինչև Սան Մարկո տանելու մասին։",\n  "carrying.title": "Carrying",\n  "carrying.when": "Հոկտեմբեր 2026",\n  "carrying.where": "Արսենալե և Կաստելլո, Վենետիկ",\n  "carrying.summary": "Մեջքի շրջանակին ամրացված կարմիր միավոր՝ տարված Արսենալեով և Կաստելլոյի փողոցներով։ Վենետիկում ամեն ինչ շարժվում է ձեռքով կամ նավակով։",\n  "murano.title": "Murano",\n  "murano.when": "Հոկտեմբեր 2026",\n  "murano.where": "Մուրանո",\n  "murano.summary": "Հնոցներ, ապակեփչողներ և զրույց սեղանի շուրջ՝ Մուրանոյի ապակու և արվեստանոցը ցուցասրահի փոխարեն կենդանի պահելու մասին։",\n  "before-the-flag.title": "Before the Flag",\n  "before-the-flag.when": "Սեպտեմբեր 2026",\n  "before-the-flag.where": "Tesa 41, Վենետիկ",\n  "before-the-flag.summary": "Սպիտակ ատամնավոր ձև դահլիճում՝ գլխապտույտ, մասշտաբ, Արսենալեի տանիքի գերաններ, և թե ինչպես է պարզ միավորը դառնում հավաքածու։",\n  "tesa-41-september.title": "In Tesa 41",\n  "tesa-41-september.when": "Սեպտեմբեր 2026",\n  "tesa-41-september.where": "Tesa 41, Վենետիկ",\n  "tesa-41-september.summary": "Իտալական դրոշը փրփրանյութի վիճակում, իրար մեջ մտնող մասեր, պիգմենտներ և վրձիններ, մինչ արվեստանոցը լցվում է գույնով։",\n  "maquette.title": "The Maquette",\n  "maquette.when": "Փետրվար 2026",\n  "maquette.where": "Լոս Անջելես",\n  "maquette.summary": "Էսքիզից եռաչափ մոդել, ապա բնական չափի փրփրանյութ՝ քառակուսիներ, ուղղանկյուններ և համամասնություն, որոնք ստուգվում են ձևի կողքին կանգնելով։",\n  "leaning-red.title": "Leaning Red",\n  "leaning-red.when": "Փետրվար 2026",\n  "leaning-red.where": "Լոս Անջելես",\n  "leaning-red.summary": "Բարձր ձևի ձեռքով կառուցում այգու արվեստանոցում՝ ստվարաթղթից և ժապավենից մինչև սենյակում կանգնած վահանակ։ Միայն երաժշտություն։"\n}\n'});
